package catalog

import "testing"

// TestG1ConstantsMatchAWSCloudValues pins every G1-category constant
// (appmesh, appstream, workspaces, elasticbeanstalk, dms, imagebuilder,
// verifiedaccess, transfer, cognito, amp) to the exact value it carried in
// package awscloud before the #6696 catalog consolidation. The consolidation
// moves declarations only: any value drift here is a behavior change, not
// a move.
